type LayoutContext = Record<
  'css' | 'header' | 'content' | 'footer',
  TemplateFunction<Record<string, unknown>>
>;
function layout<const T extends LayoutContext>({
  css,
  header,
  content,
  footer,
}: T): Template<MergedCtx<T[keyof T]>> {
  return new Template(function (ctx: MergedCtx<T[keyof T]>) {
    return html`
      <!doctype html>
      <html lang="fr">
        <head>
          <script
            defer
            crossorigin="anonymous"
            integrity="sha384-y6+mefdjvGUaOPOrIMXHgP6Wwpza9G0N1QW1YUteLiwb50olbeI7H909UwZTMuVX"
            src="https://unpkg.com/pagedjs@0.4.3/dist/paged.polyfill.min.js"
          ></script>

          <style>
            ${css(ctx)}
          </style>
        </head>
        <body>
          <header>${logo()}</header>

          <main>
            <div class="header">${header(ctx)}</div>

            <footer>
              <div class="drapeau"></div>
            </footer>

            ${content(ctx)}
          </main>

          <div class="footer">${footer(ctx)}</div>
        </body>
      </html>
    `;
  });
}

function agendaHeader(ctx: {
  sessionMeetingDate: Date;
  formation: Magistrat.Formation;
}): string {
  return html`
    <p class="formation">
      ${ctx.formation === Magistrat.Formation.SIEGE
        ? `Formation compétente à l'égard des magistrats du siège`
        : `Formation compétente à l'égard des magistrats du parquet`}
    </p>
    <h1>Avis du conseil supérieur de la magistrature</h1>
    <div class="subtitle-row">
      <p class="subtitle">Ordre du jour</p>
      <p class="date">
        Séance du ${date(ctx.sessionMeetingDate, 'do MMMM yyyy')}
      </p>
    </div>
  `;
}

function agendaNominationParagraph(
  ctx: {
    name: string;
    currentPosition: string | null;
    currentGrade: string;
    targetedPosition: string | null;
    targetedGrade: string;
    reporters: readonly string[];
  },
  index: number,
): string {
  const currentPosition = !!ctx.currentPosition
    ? `, actuellement ${ctx.currentPosition} (${ctx.currentGrade})`
    : '';
  const targetPosition = !!ctx.targetedPosition
    ? `, pour la proposition au poste de ${ctx.targetedPosition} (${ctx.targetedGrade})`
    : '';
  const reporters =
    ctx.reporters.length > 0
      ? `, au rapport de ${conjunctionList(ctx.reporters)}`
      : '';

  return html`
    <p data-file="${index}">
      <strong>${ctx.name}</strong
      >${currentPosition}${targetPosition}${reporters}.
    </p>
  `;
}

type AgendaContentCtx = Pretty<Parameters<typeof agendaNominationParagraph>[0]>;
function agendaContent(ctx: {
  nominationFiles: readonly AgendaContentCtx[];
}): string {
  return html`
    <p class="introduction">
      Sur la proposition du garde des Sceaux de nommer&nbsp;:
    </p>
    <article>
      ${ctx.nominationFiles
        .map((n, i) => agendaNominationParagraph(n, i + 1))
        .join('\n')}
    </article>
  `;
}

function agendaFooter(ctx: {
  date: Date;
  chairman: {
    firstName: string;
    lastName: string;
    title: string | null;
    gender: Gender;
  };
}): string {
  return html`
    <p class="redaction-place">
      Fait à Paris, le ${date(ctx.date, 'do MMMM yyyy')}
    </p>
    <p class="signature">${titled(ctx.chairman)}</p>
  `;
}

function agendaCss(): string {
  return /*css */ `
    :root {
      --bleu-france: rgb(0 0 145);
      --rouge-marianne: rgb(225 0 15);

      --deep-blue: rgb(51 75 111);
      --gray: rgb(153 165 183);
      --gold: rgb(197 171 103);
      --gold-light: rgb(214 188 129);
    }

    @page {
      size: A4 portrait;
      margin: 3cm 3cm 4cm 3cm;

      @bottom-center {
        content: element(footer);
      }

      @bottom-right {
        font-size: 0.8rem;
        font-weight: bold;
        content: counter(page);
      }
    }

    body {
      font-family: 'Noto Sans', sans-serif;
      font-size: 16px;
    }

    header {
      text-align: center;
      svg {
        width: 2.5cm;
      }
    }

    main {
      margin-top: 2rem;

      p {
        font-size: 0.8rem;

        &.introduction {
          margin-top: 3rem;
          font-weight: bold;
        }
      }

      article {
        margin-top: 1.5rem;

        p {
          text-indent: 2rem;
          text-align: justify;
          text-wrap: pretty;
          line-height: 1.5rem;
          break-inside: avoid;

          strong {
            font-weight: 500;
          }
        }
      }

      .header {
        text-align: center;

        .formation {
          margin: 0;
          padding: 0;
          font-style: italic;
          font-size: 0.8rem;
        }

        h1 {
          font-family: Montserrat, sans-serif;
          text-transform: uppercase;
          font-weight: 900;
          font-size: 1.2rem;
          color: var(--deep-blue);
        }

        .subtitle-row {
          margin-top: 3rem;
          display: flex;
          align-items: center;
          justify-content: space-between;
        }

        .subtitle {
          font-family: Montserrat, sans-serif;
          margin: 0;
          text-align: left;
          text-transform: uppercase;
          color: var(--gold);
          font-size: 1rem;
          font-weight: 900;
        }

        .date {
          font-size: 0.9rem;
          margin: 0;
          text-align: left;
        }
      }
    }

    .footer {
      break-before: avoid;
      break-inside: avoid;
      margin-top: 3rem;
      font-size: 0.8rem;

      .signature {
        text-align: right;
        
      }
    }

    footer {
      position: running(footer);
      height: 1px;
      width:80%;
      margin: 0 auto;

      .drapeau {
        height: 100%;
        width: 100%;
        display: flex;

        &::after,
        &::before {
          width: 33%;
          content: '';
          height: 100%;
          display: block;
        }

        &::before {
          background: var(--bleu-france);
        }
        &::after {
          background: var(--rouge-marianne);
          margin-left: 33%;
        }
      }
    }
  `;
}

export const agendaTemplate = layout({
  css: agendaCss,
  header: agendaHeader,
  content: agendaContent,
  footer: agendaFooter,
});
